import{_ as a,H as n,f as i,i as t}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"11 | 代理（上）：ReAct框架，推理与行动的协同","description":"","frontmatter":{},"headers":[{"level":2,"title":"代理的作用","slug":"代理的作用","link":"#代理的作用","children":[]},{"level":2,"title":"ReAct 框架","slug":"react-框架","link":"#react-框架","children":[]},{"level":2,"title":"通过代理实现 ReAct 框架","slug":"通过代理实现-react-框架","link":"#通过代理实现-react-框架","children":[]},{"level":2,"title":"总结时刻","slug":"总结时刻","link":"#总结时刻","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"延伸阅读","slug":"延伸阅读","link":"#延伸阅读","children":[]}],"relativePath":"LangChain实战课/11｜代理（上）：ReAct框架，推理与行动的协同.md","filePath":"LangChain实战课/11｜代理（上）：ReAct框架，推理与行动的协同.md","lastUpdated":1795530794000}'),s={name:"LangChain实战课/11｜代理（上）：ReAct框架，推理与行动的协同.md"};function p(l,e,o,h,r,g){return n(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="_11-代理-上-react框架-推理与行动的协同" tabindex="-1">11 | 代理（上）：ReAct框架，推理与行动的协同 <a class="header-anchor" href="#_11-代理-上-react框架-推理与行动的协同" aria-label="Permalink to &quot;11 | 代理（上）：ReAct框架，推理与行动的协同&quot;">​</a></h1><p>你好，我是黄佳，欢迎来到 LangChain 实战课！</p><p>在之前介绍的思维链（CoT）中，我向你展示了 LLMs 执行推理轨迹的能力。在给出答案之前，大模型通过中间推理步骤（尤其是与少样本提示相结合）能够实现复杂的推理，获得更好的结果，以完成更具挑战的任务。</p><p>然而，仅仅应用思维链推理并不能解决大模型的固有问题：无法主动更新自己的知识，导致出现事实幻觉。也就是说，因为缺乏和外部世界的接触，大模型只拥有训练时见过的知识，以及提示信息中作为上下文提供的附加知识。如果你问的问题超出它的知识范围，要么大模型向你坦白：“我的训练时间截至 XXXX 年 XX 月 XX 日”，要么它就会开始一本正经地胡说。</p><p>下面这张图就属于第二种情况，我制作的一个 Prompt 骗过了大模型，它会误以为我引述的很多虚构的东西是事实，而且它还会顺着这个思路继续胡编乱造。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/1.png" alt=""></a></p><ul><li>遇到自己不懂的东西，大模型“一本正经地胡说八道”</li></ul><p>这个问题如何解决呢？</p><p>也不难。你可以让大模型先在本地知识库中进行搜索，检查一下提示中的信息的真实性，如果真实，再进行输出；如果不真实，则进行修正。如果本地知识库找不到相应的信息，可以调用工具进行外部搜索，来检查提示信息的真实性。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/2.png" alt=""></a></p><p>上面所说的无论本地知识库还是搜索引擎，都不是封装在大模型内部的知识，我们把它们称为“外部工具”。</p><h2 id="代理的作用" tabindex="-1">代理的作用 <a class="header-anchor" href="#代理的作用" aria-label="Permalink to &quot;代理的作用&quot;">​</a></h2><p>每当你遇到这种需要模型做自主判断、自行调用工具、自行决定下一步行动的时候，Agent（也就是代理）就出场了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/3.png" alt=""></a></p><p>代理就像一个多功能的接口，它能够接触并使用一套工具。根据用户的输入，代理会决定调用哪些工具。它不仅可以同时使用多种工具，而且可以将一个工具的输出数据作为另一个工具的输入数据。</p><p>在 LangChain 中使用代理，我们只需要理解下面三个元素。</p><ul><li><p>大模型：提供逻辑的引擎，负责生成预测和处理输入。</p></li><li><p>与之交互的外部工具：可能包括数据清洗工具、搜索引擎、应用程序等。</p></li><li><p>控制交互的代理：调用适当的外部工具，并管理整个交互过程的流程。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/4.png" alt=""></a></p><ul><li>代理接收任务后，会自动调用工具，给出答案</li></ul><p>上面的思路看似简单，其实很值得我们仔细琢磨。</p><p>这个过程有很多地方需要大模型自主判断下一步行为（也就是操作）要做什么，如果不加引导，那大模型本身是不具备这个能力的。比如下面这一系列的操作：</p><ul><li><p>什么时候开始在本地知识库中搜索（这个比较简单，毕竟是第一个步骤，可以预设）？</p></li><li><p>怎么确定本地知识库的检索已经完成，可以开始下一步？</p></li><li><p>调用哪一种外部搜索工具（比如 Google 引擎）？</p></li><li><p>如何确定外部搜索工具返回了想要找的内容？</p></li><li><p>如何确定信息真实性的检索已经全部完成，可以开始下一步？</p></li></ul><p>那么，LangChain 中的代理是怎样自主计划、自行判断，并执行行动的呢？</p><h2 id="react-框架" tabindex="-1">ReAct 框架 <a class="header-anchor" href="#react-框架" aria-label="Permalink to &quot;ReAct 框架&quot;">​</a></h2><p>这里我要请你思考一下：如果你接到一个新任务，你将如何做出决策并完成下一步的行动？</p><p>比如说，你在运营花店的过程中，经常会经历天气变化而导致的鲜花售价变化，那么，每天早上你会如何为你的鲜花定价？</p><p>也许你会告诉我，我会去 Google 上面查一查今天的鲜花成本价啊（行动），也就是我预计的进货的价格，然后我会根据这个价格的高低（观察），来确定我要加价多少（思考），最后计算出一个售价（行动）！</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/5.png" alt=""></a></p><ul><li>定价过程</li></ul><p>你看，在这个简单的例子中，你有观察、有思考，然后才会具体行动。这里的观察和思考，我们统称为推理（Reasoning）过程，推理指导着你的行动（Acting）。</p><p>我们今天要讲的 ReAct 框架的灵感正是来自“行动”和“推理”之间的协同作用，这种协同作用使得咱们人类能够学习新任务并做出决策或推理。这个框架，也是大模型能够作为“智能代理”，自主、连续、交错地生成推理轨迹和任务特定操作的理论基础。</p><p>先和你说明一点，此 ReAct 并非指代流行的前端开发框架 React，它在这里专指如何指导大语言模型推理和行动的一种思维框架。这个思维框架是 Shunyu Yao 等人在 ICLR 2023 会议论文《ReAct: Synergizing Reasoning and Acting in Language Models》（ReAct：在语言模型中协同推理和行动）中提出的。</p><p>这篇文章的一个关键启发在于：大语言模型可以通过生成推理痕迹和任务特定行动来实现更大的协同作用。</p><p>具体来说，就是引导模型生成一个任务解决轨迹：观察环境 - 进行思考 - 采取行动，也就是观察 - 思考 - 行动。那么，再进一步进行简化，就变成了推理 - 行动，也就是 Reasoning-Acting框架。</p><p>其中，Reasoning 包括了对当前环境和状态的观察，并生成推理轨迹。这使模型能够诱导、跟踪和更新操作计划，甚至处理异常情况。Acting 在于指导大模型采取下一步的行动，比如与外部源（如知识库或环境）进行交互并且收集信息，或者给出最终答案。</p><p>ReAct 的每一个推理过程都会被详细记录在案，这也改善大模型解决问题时的可解释性和可信度，而且这个框架在各种语言和决策任务中都得到了很好的效果。</p><p>下面让我们用一个具体的示例来说明这一点。比如我给出大模型这样一个任务：在一个虚拟环境中找到一个胡椒瓶并将其放在一个抽屉里。</p><p>在这个任务中，没有推理能力的模型不能够在房间的各个角落中进行寻找，或者在找到胡椒瓶之后不能够判断下一步的行动，因而无法完成任务。如果使用 ReAct，这一系列子目标将被具体地捕获在每一个思考过程中。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/6.png" alt=""></a></p><ul><li>通过 ReAct 思维框架，大模型成功找到胡椒瓶</li></ul><p>现在，让我们回到开始的时候我们所面临的问题。仅仅使用思维链（CoT）提示，LLMs 能够执行推理轨迹，以完成算术和常识推理等问题，但这样的模型因为缺乏和外部世界的接触或无法更新自己的知识，会导致幻觉的出现。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/7.png" alt=""></a></p><ul><li>从仅使用 CoT，仅执行 Action，到 ReAct</li></ul><p>而将 ReAct 框架和思维链（CoT）结合使用，则能够让大模型在推理过程同时使用内部知识和获取到的外部信息，从而给出更可靠和实际的回应，也提高了 LLMs 的可解释性和可信度。</p><p>LangChain 正是通过 Agent 类，将 ReAct 框架进行了完美封装和实现，这一下子就赋予了大模型极大的自主性（Autonomy），你的大模型现在从一个仅仅可以通过自己内部知识进行对话聊天的 Bot，飞升为了一个有手有脚能使用工具的智能代理。</p><p>ReAct 框架会提示 LLMs 为任务生成推理轨迹和操作，这使得代理能系统地执行动态推理来创建、维护和调整操作计划，同时还支持与外部环境（例如 Google 搜索、Wikipedia）的交互，以将额外信息合并到推理中。</p><h2 id="通过代理实现-react-框架" tabindex="-1">通过代理实现 ReAct 框架 <a class="header-anchor" href="#通过代理实现-react-框架" aria-label="Permalink to &quot;通过代理实现 ReAct 框架&quot;">​</a></h2><p>下面，就让我们用 LangChain 中最为常用的 ZERO_SHOT_REACT_DESCRIPTION ——这种常用代理类型，来剖析一下 LLM 是如何在 ReAct 框架的指导之下进行推理的。</p><p>此处，我们要给代理一个任务，这个任务是找到玫瑰的当前市场价格，然后计算出加价 15%后的新价格。</p><p>在开始之前，有一个准备工作，就是你需要在 serpapi.com 注册一个账号，并且拿到你的SERPAPI_API_KEY，这个就是我们要为大模型提供的 Google 搜索工具。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/8.png" alt=""></a></p><p>先安装 SerpAPI 的包。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pip install google-search-results</span></span></code></pre></div><p>设置好 OpenAI 和 SerpAPI 的 API 密钥。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 设置OpenAI和SERPAPI的API密钥</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">os.environ[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OPENAI_API_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Your OpenAI API Key&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">os.environ[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SERPAPI_API_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Your SerpAPI API Key&#39;</span></span></code></pre></div><p>再导入所需的库。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>from langchain.agents import load_tools</span></span>
<span class="line"><span>from langchain.agents import initialize_agent</span></span>
<span class="line"><span>from langchain.agents import AgentType</span></span>
<span class="line"><span>from langchain.llms import OpenAI</span></span></code></pre></div><p>然后加载将用于控制代理的语言模型。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>llm = OpenAI(temperature=0)</span></span></code></pre></div><p>接下来，加载一些要使用的工具，包括 serpapi（这是调用 Google 搜索引擎的工具）以及llm-math（这是通过 LLM 进行数学计算的工具）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tools = load_tools([&quot;serpapi&quot;, &quot;llm-math&quot;], llm=llm)</span></span></code></pre></div><p>最后，让我们使用工具、语言模型和代理类型来初始化代理。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent = initialize_agent(tools, llm, agent=AgentType.ZERO_SHOT_REACT_DESCRIPTION,</span></span></code></pre></div><p>好了，现在我们让代理来回答我刚才提出的问题了！目前市场上玫瑰花的平均价格是多少？如果我在此基础上加价 15% 卖出，应该如何定价？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent.run(&quot;目前市场上玫瑰花的平均价格是多少？如果我在此基础上加价15%卖出，应该如何定价？&quot;)</span></span></code></pre></div><p>大模型成功遵循了 ReAct 框架，它输出的思考与行动轨迹如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; Entering new  chain...</span></span>
<span class="line"><span>I need to find the current market price of roses and then calculate the new pric</span></span>
<span class="line"><span>Action: Search</span></span>
<span class="line"><span>Action Input: &quot;Average price of roses&quot;</span></span>
<span class="line"><span>Observation: According to the study, the average price for a dozen roses in the U</span></span>
<span class="line"><span>Thought: I need to calculate the new price with a 15% markup.</span></span>
<span class="line"><span>Action: Calculator</span></span>
<span class="line"><span>Action Input: 80.16 * 1.15</span></span>
<span class="line"><span>Observation: Answer: 92.18399999999998</span></span>
<span class="line"><span>Thought: I now know the final answer.</span></span>
<span class="line"><span>Final Answer: The new price with a 15% markup would be $92.18.</span></span>
<span class="line"><span>&gt; Finished chain.</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/9.png" alt=""></a></p><p>可以看到，ZERO_SHOT_REACT_DESCRIPTION 类型的智能代理在 LangChain 中，自动形成了一个完善的思考与行动链条，而且给出了正确的答案。</p><p>你可以对照下面这个表格，再巩固一下这个链条中的每一个环节。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LangChain%E5%AE%9E%E6%88%98%E8%AF%BE/images/11/10.png" alt=""></a></p><p>这个思维链条中，智能代理有思考、有观察、有行动，成功通过搜索和计算两个操作，完成了任务。在下一讲中，我们将继续深入剖析 LangChain 中的不同类型的代理，并利用它完成更为复杂的任务。</p><h2 id="总结时刻" tabindex="-1">总结时刻 <a class="header-anchor" href="#总结时刻" aria-label="Permalink to &quot;总结时刻&quot;">​</a></h2><p>这节课我们介绍了什么是 LangChain 中的代理，更重要的是，我们介绍了代理自主行动的驱动力—— ReAct 框架。</p><p>通过 ReAct 框架，大模型将被引导生成一个任务解决轨迹，即观察环境 - 进行思考 - 采取行动。观察和思考阶段被统称为推理（Reasoning），而实施下一步行动的阶段被称为行动（Acting）。在每一步推理过程中，都会详细记录下来，这也改善了大模型解决问题时的可解释性和可信度。</p><ul><li><p>在推理阶段，模型对当前环境和状态进行观察，并生成推理轨迹，从而使模型能够诱导、跟踪和更新操作计划，甚至处理异常情况。</p></li><li><p>在行动阶段，模型会采取下一步的行动，如与外部源（如知识库或环境）进行交互并收集信息，或给出最终答案。</p></li></ul><p>ReAct 框架的这些优点，使得它在未来的发展中具有巨大的潜力。随着技术的进步，我们可以期待 ReAct 框架将能够处理更多、更复杂的任务。特别是随着具身智能的发展，ReAct 框架将能够使智能代理在虚拟或实际环境中进行更复杂的交互。例如，智能代理可能会在虚拟环境中进行导航，或者在实际环境中操作物理对象。这将大大扩展 AI 的应用范围，使得它们能够更好地服务于我们的生活和工作。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>在 ReAct 框架中，推理和行动各自代表什么？其相互之间的关系如何？</p></li><li><p>为什么说 ReAct 框架能改善大模型解决问题时的可解释性和可信度？</p></li><li><p>你能否说一说 LangChain 中的代理和链的核心差异？</p></li></ol><p>期待在留言区看到你的思考，如果你觉得内容对你有帮助，也欢迎分享给有需要的朋友！最后如果你学有余力，可以进一步学习下面延伸阅读的两篇论文。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ol><li><p>论文，ReAct：在语言模型中协同推理和行动，Yao, S., Zhao, J., Yu, D., Du, N.,Shafran, I., Narasimhan, K., &amp; Cao, Y. (2023). ReAct: Synergizing Reasoning and Actingin Language Models. arXiv preprint arXiv:2210.03629</p></li><li><p>论文，ART：大型语言模型的自动多步推理和工具使用， Paranjape, B., Lundberg, S.,Singh, S., Hajishirzi, H., Zettlemoyer, L., &amp; Ribeiro, M. T. (2023). ART: Automatic multi-stepreasoning and tool-use for large language models. arXiv preprint arXiv:2303.09014.</p></li></ol>`,82)])])}const E=a(s,[["render",p]]);export{u as __pageData,E as default};
